<template>
  <div class="app-container pipeline-page pipeline-model-page">
    <div class="pipeline-page-head"><div><span class="pipeline-eyebrow">MODEL & PROMPT</span><h1>模型与 Prompt</h1><p class="summary">集中配置模型网关、业务场景参数和 Prompt 版本，所有变更均进入审计记录。</p></div><div class="pipeline-head-actions"><el-button :icon="DocumentChecked" @click="auditVisible = true">变更记录</el-button><el-button type="primary" :icon="Plus" @click="openModelDialog">添加模型</el-button></div></div>
    <div class="model-overview"><article><span>可用模型</span><strong>4 / 5</strong><small class="is-success">服务正常</small></article><article><span>今日调用</span><strong>2,846</strong><small>成功率 99.2%</small></article><article><span>平均响应</span><strong>3.8s</strong><small>较昨日 -0.4s</small></article><article><span>Prompt 版本</span><strong>18</strong><small>3 个待发布</small></article></div>
    <el-tabs v-model="activeTab" class="model-tabs">
      <el-tab-pane label="模型配置" name="models"><div class="model-grid"><article v-for="model in models" :key="model.id"><header><span class="model-logo" :style="{ background: model.color }">{{ model.short }}</span><div><strong>{{ model.name }}</strong><small>{{ model.provider }} · {{ model.protocol }}</small></div><el-switch v-model="model.enabled" /></header><dl><div><dt>适用场景</dt><dd>{{ model.scenes.join('、') }}</dd></div><div><dt>上下文长度</dt><dd>{{ model.context }}</dd></div><div><dt>温度参数</dt><dd>{{ model.temperature }}</dd></div><div><dt>最近检测</dt><dd>{{ model.checkedAt }}</dd></div></dl><footer><span :class="{ 'is-error': model.health !== '正常' }"><i></i>{{ model.health }}</span><div><el-button link @click="testModel(model)">连通测试</el-button><el-button link type="primary" @click="editModel(model)">配置</el-button></div></footer></article></div></el-tab-pane>
      <el-tab-pane label="Prompt 管理" name="prompts"><div class="prompt-layout"><aside><button v-for="scene in scenes" :key="scene.value" type="button" :class="{ 'is-active': activeScene === scene.value }" @click="activeScene = scene.value"><component :is="scene.icon" /><span><strong>{{ scene.name }}</strong><small>{{ scene.description }}</small></span><b>{{ promptCount(scene.value) }}</b></button></aside><main><div class="prompt-toolbar"><el-input v-model="promptKeyword" :prefix-icon="Search" clearable placeholder="搜索 Prompt 名称或用途" /><el-button type="primary" :icon="Plus" @click="openPromptDialog">新建 Prompt</el-button></div><el-table :data="filteredPrompts"><el-table-column prop="name" label="Prompt 名称" min-width="240"><template #default="{ row }"><div class="prompt-name"><strong>{{ row.name }}</strong><small>{{ row.description }}</small></div></template></el-table-column><el-table-column prop="version" label="当前版本" width="100" /><el-table-column prop="model" label="默认模型" width="160" /><el-table-column label="状态" width="100"><template #default="{ row }"><el-tag :type="row.status === 'published' ? 'success' : 'warning'" effect="plain">{{ row.status === 'published' ? '已发布' : '草稿' }}</el-tag></template></el-table-column><el-table-column prop="updatedAt" label="更新时间" width="150" /><el-table-column label="操作" width="160"><template #default="{ row }"><el-button link type="primary" @click="editPrompt(row)">编辑</el-button><el-button link @click="ElMessage.info('已打开版本对比')">版本</el-button><el-button link @click="ElMessage.success('测试任务已创建')">测试</el-button></template></el-table-column></el-table></main></div></el-tab-pane>
      <el-tab-pane label="场景路由" name="routing"><el-card shadow="never"><el-table :data="sceneRoutes"><el-table-column prop="scene" label="业务场景" min-width="220" /><el-table-column prop="primary" label="主模型" min-width="180" /><el-table-column prop="fallback" label="备用模型" min-width="180" /><el-table-column prop="timeout" label="超时" width="100" /><el-table-column prop="dailyLimit" label="日限额" width="120" /><el-table-column label="操作" width="100"><template #default><el-button link type="primary">编辑路由</el-button></template></el-table-column></el-table></el-card></el-tab-pane>
    </el-tabs>
    <el-dialog v-model="modelDialogVisible" :title="editingModel ? '配置模型' : '添加模型'" width="620px"><el-form label-position="top"><div class="model-form-grid"><el-form-item label="模型名称"><el-input v-model="modelForm.name" /></el-form-item><el-form-item label="服务商"><el-input v-model="modelForm.provider" /></el-form-item><el-form-item label="接口地址" class="is-full"><el-input v-model="modelForm.endpoint" /></el-form-item><el-form-item label="模型标识"><el-input v-model="modelForm.modelId" /></el-form-item><el-form-item label="协议类型"><el-select v-model="modelForm.protocol"><el-option label="OpenAI Compatible" value="openai" /><el-option label="Custom Gateway" value="custom" /></el-select></el-form-item><el-form-item label="API 密钥" class="is-full"><el-input v-model="modelForm.apiKey" type="password" show-password placeholder="密钥仅加密保存，不会在页面回显" /></el-form-item></div></el-form><template #footer><el-button @click="modelDialogVisible = false">取消</el-button><el-button @click="ElMessage.success('连通测试通过')">测试连接</el-button><el-button type="primary" @click="saveModel">保存配置</el-button></template></el-dialog>
    <el-drawer v-model="promptDialogVisible" :title="editingPrompt ? '编辑 Prompt' : '新建 Prompt'" size="720px"><el-form label-position="top"><el-form-item label="Prompt 名称"><el-input v-model="promptForm.name" /></el-form-item><el-form-item label="系统提示词"><el-input v-model="promptForm.system" type="textarea" :rows="8" /></el-form-item><el-form-item label="用户提示词模板"><el-input v-model="promptForm.user" type="textarea" :rows="8" /></el-form-item><el-alert title="支持变量：{{title}}、{{materials}}、{{outline}}、{{requirements}}。发布前必须通过离线测试集。" type="info" :closable="false" /></el-form><template #footer><el-button @click="promptDialogVisible = false">取消</el-button><el-button>运行测试集</el-button><el-button type="primary" @click="savePrompt">保存新版本</el-button></template></el-drawer>
    <el-drawer v-model="auditVisible" title="模型与 Prompt 变更记录" size="560px"><el-timeline><el-timeline-item v-for="item in auditLogs" :key="item.time" :timestamp="item.time" placement="top"><el-card shadow="never"><strong>{{ item.action }}</strong><p>{{ item.detail }}</p><small>{{ item.user }}</small></el-card></el-timeline-item></el-timeline></el-drawer>
