import { computed, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { ChatDotRound, Document, DocumentChecked, MagicStick, Plus, Search, Tickets } from '@element-plus/icons-vue'

const activeTab = ref('models')
const activeScene = ref('all')
const promptKeyword = ref('')
const modelDialogVisible = ref(false)
const promptDialogVisible = ref(false)
const auditVisible = ref(false)
const editingModel = ref(null)
const editingPrompt = ref(null)
const models = ref([{ id: 1, short: 'R1', name: '科研写作主模型', provider: '企业模型网关', protocol: 'OpenAI Compatible', scenes: ['科研生成', '摘要'], context: '128K', temperature: 0.3, checkedAt: '5分钟前', health: '正常', enabled: true, color: '#2764e7' }, { id: 2, short: 'R2', name: '长文本分析模型', provider: '企业模型网关', protocol: 'OpenAI Compatible', scenes: ['文档解析', '质量检查'], context: '256K', temperature: 0.2, checkedAt: '8分钟前', health: '正常', enabled: true, color: '#0b8f87' }, { id: 3, short: 'T1', name: '中英翻译模型', provider: '内部推理服务', protocol: 'Custom Gateway', scenes: ['论文翻译'], context: '64K', temperature: 0.1, checkedAt: '12分钟前', health: '正常', enabled: true, color: '#7357c8' }, { id: 4, short: 'V1', name: '图形生成模型', provider: '内部推理服务', protocol: 'Custom Gateway', scenes: ['技术路线图'], context: '32K', temperature: 0.4, checkedAt: '26分钟前', health: '响应偏慢', enabled: true, color: '#c26a2e' }])
const scenes = [{ name: '全部 Prompt', value: 'all', description: '查看所有业务提示词', icon: Document }, { name: '科研报告', value: 'research', description: '大纲与章节生成', icon: MagicStick }, { name: '日报周月报', value: 'digest', description: '摘要与周期趋势研判', icon: Tickets }, { name: '知识问答', value: 'qa', description: 'RAG 回答与引用', icon: ChatDotRound }]
const prompts = ref([{ id: 1, scene: 'research', name: '科研报告大纲规划', description: '根据任务参数和资料覆盖生成章节结构', version: 'V2.4', model: '科研写作主模型', status: 'published', updatedAt: '2026-08-02' }, { id: 2, scene: 'research', name: '科研章节生成', description: '基于证据块生成带引用的章节内容', version: 'V3.1', model: '科研写作主模型', status: 'published', updatedAt: '2026-08-01' }, { id: 3, scene: 'digest', name: '单条资讯摘要', description: '生成 150-200 字客观摘要', version: 'V1.8', model: '长文本分析模型', status: 'published', updatedAt: '2026-07-30' }, { id: 4, scene: 'digest', name: '热点研判生成', description: '从周期情报中提炼趋势与影响', version: 'V1.3', model: '科研写作主模型', status: 'draft', updatedAt: '2026-07-29' }, { id: 5, scene: 'qa', name: '知识问答证据回答', description: '仅基于授权片段回答并返回引用', version: 'V2.0', model: '长文本分析模型', status: 'published', updatedAt: '2026-07-26' }])
const sceneRoutes = [{ scene: '科研报告生成', primary: '科研写作主模型', fallback: '长文本分析模型', timeout: '120s', dailyLimit: '2,000次' }, { scene: '文档解析与摘要', primary: '长文本分析模型', fallback: '科研写作主模型', timeout: '90s', dailyLimit: '5,000次' }, { scene: '知识问答', primary: '长文本分析模型', fallback: '科研写作主模型', timeout: '45s', dailyLimit: '8,000次' }, { scene: '技术路线图', primary: '图形生成模型', fallback: '科研写作主模型', timeout: '90s', dailyLimit: '1,000次' }]
const modelForm = reactive({ name: '', provider: '', endpoint: '', modelId: '', protocol: 'openai', apiKey: '' })
const promptForm = reactive({ name: '', system: '你是管网科研辅助平台的专业写作助手。所有结论必须基于给定证据。', user: '研究主题：{{title}}\n资料：{{materials}}\n要求：{{requirements}}' })
const auditLogs = [{ time: '2026-08-04 10:16', action: '发布 Prompt V3.1', detail: '科研章节生成 Prompt 通过 120 条离线测试集。', user: '管理员' }, { time: '2026-08-03 17:42', action: '更新模型路由', detail: '知识问答备用模型调整为科研写作主模型。', user: '平台运维' }, { time: '2026-08-02 09:30', action: '修改模型参数', detail: '科研写作主模型 temperature 从 0.4 调整为 0.3。', user: '算法工程师' }]
const filteredPrompts = computed(() => prompts.value.filter(item => (activeScene.value === 'all' || item.scene === activeScene.value) && (!promptKeyword.value || `${item.name}${item.description}`.includes(promptKeyword.value))))
function promptCount(scene) { return scene === 'all' ? prompts.value.length : prompts.value.filter(item => item.scene === scene).length }
function openModelDialog() { editingModel.value = null; Object.assign(modelForm, { name: '', provider: '', endpoint: '', modelId: '', protocol: 'openai', apiKey: '' }); modelDialogVisible.value = true }
function editModel(model) { editingModel.value = model; Object.assign(modelForm, { name: model.name, provider: model.provider, endpoint: 'https://model-gateway.example/v1', modelId: model.name, protocol: 'openai', apiKey: '' }); modelDialogVisible.value = true }
function saveModel() { modelDialogVisible.value = false; ElMessage.success('模型配置已保存并记录审计日志') }
function testModel(model) { ElMessage.success(`${model.name} 连通测试通过，响应 3.2 秒`) }
function openPromptDialog() { editingPrompt.value = null; promptForm.name = ''; promptDialogVisible.value = true }
function editPrompt(prompt) { editingPrompt.value = prompt; promptForm.name = prompt.name; promptDialogVisible.value = true }
function savePrompt() { promptDialogVisible.value = false; ElMessage.success('Prompt 新版本已保存为草稿') }
</script>

